        require(contract_address != address(c));
        require(contract_address != address(this));

        bool reverted;
        try c.transfer(contract_address, tos, vs) returns (bool ok) {
            reverted = false;
            assert(ok);
        } catch {
            reverted = true;
        }

        // General rule: transfer succeeds only when the batch is non-empty,
        // lengths match, and every underlying transferFrom call succeeds.
        // If it reverts, the caller receives no successful return value, and
        // the whole batch is all-or-nothing.
